function resHandler(answer) {

    if (answer == "true" || answer == true) {
        g_form.addErrorMessage("Handler Tasks are currently in Progress for this Bulk.");
        return false;
    }
    var gajax = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkUtils");
    gajax.addParam("sysparm_name", "getCountOfTask");
    gajax.addParam("sysparm_bulkid", g_form.getUniqueValue());
    gajax.getXMLAnswer(response);
}

function response(answer) {

    var outcomeval = g_form.getValue('outcome').toString();

    // MSSCUSTODY-3282 - Verify Task Count before submitting the bulk
    // MSSCUSTODY-4282
    var expectedTasksCount = g_form.getValue("active_trade_count");
    //var expectedTasksCount = g_scratchpad.active_trades; // added as part of MSSCUSTODY - 5407 & MSSCUSTODY-5580
    // MSSCUSTODY 4282
    if (expectedTasksCount == 0) {
        g_form.addErrorMessage("This Bulk does not have any Trades Linked due to GHSS Update");
        return false;
    }
    // Comparing the ExpectedLinkedTrades with current Linked Trades
    if (expectedTasksCount == answer) {
        if (g_form.getValue('outcome') == 'Review and closed the task') {
            var conf1 = confirm('No task will be submitted to checker.\nDo you want to proceed?');
        } else {
            var conf = confirm('Number of task submitted to checker : ' + expectedTasksCount + '\nDo you want to proceed?');
        }
    } else {
        if (g_form.getValue('outcome') == 'Review and closed the task') {
            conf1 = confirm('No task will be submitted to checker.\nDo you want to proceed?');
        } else {
            // if (expectedTasksCount == 0 || expectedTasksCount < answer) {
            //     conf = confirm('Number of task submitted to checker: ' + answer + '\nDo you want to proceed?');
            // } else {
            // MSSCUSTODY-4282, if count does not match then it means that linking is in progress
            g_form.addErrorMessage("Unable to submit. Linking of tasks is in progress with this Bulk");
            return false;
            // }
        }
    }
    if (conf || conf1) {
        //gsftSubmit(null, g_form.getFormElement(), 'submit_bulk');
        g_form.save().then(function() {
            g_aw.closeRecord();
            var bulktype = g_scratchpad.bulktype;
            if (bulktype == 'automated_task') { // Redirect to Bulk automated task
                setTimeout(function() {
                    top.window.location = "/x/hsb11/mss-custody-workspace/list/params/list-id/07bc17521bbe9a902ac120a8b04bcb69";
                }, 5);
            } else if (bulktype == 'manual_task') { // Redirect to manual maintenance task
                setTimeout(function() {
                    top.window.location = "/x/hsb11/mss-custody-workspace/list/params/list-id/bf8e5bc31be616502ac120a8b04bcbf2";
                }, 5);
            }
        });

        //var gajax = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkUtils");
        //var gajax = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkProcessUtils"); //MSSOTIQUBE-2465 new script include and function
        var gajax = new GlideAjax("x_hsb11_mss_c_proc.MSSCustodyBulkEventCallUtils");
        gajax.addParam("sysparm_name", "call_updateMakerTask");
        gajax.addParam("sysparm_bulkid", g_form.getUniqueValue());
        gajax.addParam("sysparm_assignmentgroup", g_form.getValue('assignment_group'));
        gajax.addParam("sysparm_assignedto", g_form.getValue('assigned_to'));
        gajax.addParam("sysparm_outcome", g_form.getValue('outcome'));
        gajax.addParam("sysparm_advice", g_form.getValue('advice'));
        gajax.addParam("sysparm_reasoncode", g_form.getValue('reason_code'));
        gajax.addParam("sysparm_reasondescription", g_form.getValue('reason_description'));
        gajax.addParam("sysparm_suspend", g_form.getValue('suspend'));
        gajax.addParam("sysparm_cancelby", g_form.getValue('cancel_by'));
        gajax.addParam("sysparm_settlementtype", g_form.getValue('settlement_type'));
        gajax.addParam("sysparm_bktobk", g_form.getValue('bk_to_bk_info'));
        gajax.addParam("sysparm_cancellationreference", g_form.getValue('cancellation_reference'));
        gajax.addParam("sysparm_collectcancelcharge", g_form.getValue('collect_cancel_charge'));
        // added as part of 4901
        gajax.addParam("sysparm_settDate", g_form.getValue('settlement_date'));
        gajax.addParam("sysparm_fxrTD", g_form.getValue('fxr_td'));
        gajax.addParam("sysparm_valDate", g_form.getValue('value_date'));


        // MSSCUSTODY-6379
        gajax.addParam("sysparm_comments", g_form.getValue('comments'));
        gajax.addParam("sysparm_tasksCount", expectedTasksCount); //MSSOTIQUBE-2465 

        // MSSCUSTODY-6821
        var uploadType = '';
        if (typeof g_scratchpad.uploadType !== 'undefined') {
            uploadType = g_scratchpad.uploadType;
        }
        gajax.addParam("sysparm_uploadType", uploadType);


        //MSSCUSTODY - 6087
        gajax.addParam("sysparm_fxcx", g_form.getValue('fx_cx'));
        gajax.addParam("sysparm_gdi", g_form.getValue('gdi'));

        //MSSCUSTODY-7266
        gajax.addParam("sysparm_subOutcome", g_form.getValue('sub_outcome'));
        gajax.addParam("sysparm_transRef", g_form.getValue('transaction_reference'));
        gajax.addParam("sysparm_transType", g_form.getValue('transaction_type_display'));
        gajax.addParam("sysparm_legStatus", g_form.getValue('legacy_status_display'));
        gajax.addParam("sysparm_switchRef", g_form.getValue('pair_switch_reference'));
        gajax.addParam("sysparm_counterpartyCode", g_form.getValue('amend_counterparty_code_ref'));

        gajax.getXMLAnswer(response);

        function response(answer) {}

        //use event queue to call update task function


    } else {
        location.reload();
    }

}

function filterForMissingMandatoryFields(field) {
    // Check if the field is mandatory
    if (g_form.isMandatory(field)) {
        // Return true if there is no value
        return !g_form.getValue(field);
    }
}

function getMissingFields() {
    // Get all fields
    var fieldList = g_form.getFieldNames();

    // Return only mandatory fields that have no value
    return fieldList.filter(filterForMissingMandatoryFields);
}
